import { readFileSync, writeFileSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";

const root = join(dirname(fileURLToPath(import.meta.url)), "..");
const source = join(root, "src/assets/leases/moi-residential-1130708.txt");
const target = join(root, "src/assets/leases/moi-residential-1130708.ts");
const text = readFileSync(source, "utf8");

const body = `// Generated by scripts/embed-lease-template.mjs from src/assets/leases/moi-residential-1130708.txt.
// Do not edit. The .txt file is the versioned official text; this module is what the Worker bundles.
export const officialLeaseTemplateText: string = ${JSON.stringify(text)};
`;

writeFileSync(target, body);
